var ITEMS=[["Mise-en-scene","Everything placed before the camera."], ["Cinematography","The art of the camera image."], ["Montage","Assembled sequence compressing time."], ["Continuity editing","Invisible seamless cutting."], ["Jump cut","Abrupt time-skip cut."], ["Match cut","Cut linking similar shapes."], ["Cross-cutting","Alternating parallel action."], ["Long take","Extended unbroken shot."], ["Tracking shot","Camera moving alongside action."], ["Dolly zoom","Zoom plus dolly: the vertigo effect."], ["Aerial shot","From above."], ["Close-up","Face-filling intimacy."], ["Extreme close-up","Detail magnified."], ["Wide shot","Full scene context."], ["Over-the-shoulder","Dialogue framing."], ["POV shot","Character's viewpoint."], ["Dutch angle","Tilted unease."], ["Steadicam","Stabilized moving camera."], ["Diegetic sound","Sound from the story world."], ["Non-diegetic sound","Sound outside the story: score."], ["Foley","Recreated everyday sounds."], ["ADR","Re-recorded dialogue."], ["Score","Original composed music."], ["Soundtrack","All released music."], ["Three-act structure","Setup, confrontation, resolution."], ["Inciting incident","The event launching the plot."], ["MacGuffin","The sought object."], ["Red herring","Misleading clue."], ["Chekhov's gun","Planted elements must pay off."], ["Deus ex machina","Contrived rescue."], ["Character arc","Inner transformation."], ["Subplot","Secondary storyline."], ["Cold open","Pre-credits scene."], ["Cliffhanger","Suspense ending."], ["Logline","One-sentence pitch."], ["Treatment","Prose story summary."], ["Spec script","Unsold sample screenplay."], ["Greenlight","Approval to produce."], ["Box office","Ticket revenue."], ["Rotten Tomatoes","Review aggregator."], ["Auteur","Director as author."], ["Genre","Category conventions."], ["Noir","Dark crime style."], ["Neorealism","Postwar Italian realism."], ["New Wave","French rule-breaking 60s."], ["Method acting","Emotional immersion technique."], ["Blocking","Planned actor movement."], ["Improv","Unscripted performance."], ["Stunt double","Risk stand-in."], ["Practical effects","In-camera physical effects."], ["CGI","Computer-generated imagery."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
